  "bots.setup.guide.createNote":
    "まず右側の手順で第三者側の認証情報を準備してから、戻って「テストして続ける」をクリックしてください。",
  "bots.setup.callbackUrlTitle": "コールバックURL",
  "bots.setup.callbackUrlDescription.webhook":
    "外部システムからの受信メッセージのコールバックは、このアドレスに送信してください。非同期の送信側の返信は、左側で入力したWebhook URLを引き続き使用します。",
  "bots.setup.callbackUrlDescription.webhookBind":
    "Webhook連携でも同じエンドポイントを使います。text = /bind <code> の個人チャット用コールバックリクエストをここへ送信してください。",
  "bots.setup.guide.telegram.create.1": "Telegramで@BotFatherを開き、新しいボットを作成します。",
  "bots.setup.guide.telegram.create.2":
    "BotFatherが返すHTTP APIトークンをコピーし、このフォームに貼り付けてください。",
  "bots.setup.guide.telegram.create.3":
    "後で連携コマンドを個人チャットで送る必要があるため、今のうちにそのボットの個人チャットを開いておくと便利です。",
  "bots.setup.guide.telegram.bind.1":
    "Telegramに戻り、作成したボットとの個人チャットを開いてください。",
  "bots.setup.guide.telegram.bind.2":
    "まだ会話を開始していない場合は、先にStartを押すか何かメッセージを送ってから、{command}を送信してください。",
  "bots.setup.guide.telegram.bind.3": "Telegramで連携成功の通知が届いたら、ここに戻ってください。",
  "bots.setup.guide.weixin.create.1":
    "WeixinのQRコードログインを開始し、Weixinでスキャンしてスマートフォン側で確認してください。",
  "bots.setup.guide.weixin.create.2":
    "ZCodeはiLinkから返されるbot_tokenを自動で保存します。スキャン後、Weixinでボットに何かメッセージを送ってチャットを有効化してください。",
  "bots.setup.guide.weixin.create.3":
    "ZCodeは内蔵のiLinkクライアントを使用し、`/ilink/bot/getupdates`でロングポーリングによりメッセージを受信し、`/ilink/bot/sendmessage`で返信します。",
  "bots.setup.guide.weixin.bind.1": "連携したいWeixinの個人チャットを開いてください。",
  "bots.setup.guide.weixin.bind.2": "{command}を送信してください。",
  "bots.setup.guide.weixin.bind.3":
    "連携成功後、ここに戻ってワークスペースとCLIの既定値の設定を完了してください。",
  "bots.setup.guide.feishu.create.1":
    "Feishu/Larkの開発者コンソールで自社製アプリを作成し、ボット機能を有効にしてください。",
  "bots.setup.guide.feishu.create.2":
    "App IDとApp Secretをコピーし、`im.message.receive_v1`とカードアクションの永続接続イベントを有効にしてください。",
  "bots.setup.guide.feishu.create.3":
    "ここで対応するFeishuまたはLarkのドメインを選択し、認証情報をフォームに貼り付けてください。",
  "bots.setup.guide.feishu.bind.1":
    "アプリをテナントにインストールし、そのボットとの個人チャットを開いてください。",
  "bots.setup.guide.feishu.bind.2": "その個人チャットで{command}を送信してください。",
  "bots.setup.guide.feishu.bind.3":
    "連携成功後、ここに戻ってワークスペースとCLIの既定値の設定を完了してください。",
  "bots.setup.guide.webhook.create.1":
    "Webhookモードでは、第三者製品側にネイティブなボットを用意する必要はありません。あなたのシステムがZCodeへメッセージをPOSTできれば十分です。",
  "bots.setup.guide.webhook.create.2":
    "まず共有シークレットを決めてください。非同期の返信を受け取りたい場合は、送信側のWebhook URLも入力してください。",
  "bots.setup.guide.webhook.create.3":
    "外部ユーザーごとに安定したuserIdを保つことで、連携とその後のコンテキストが同じ人物に対応します。",
  "bots.setup.guide.webhook.bind.1":
    "ZCodeの`/api/bots/webhook`エンドポイントに、個人メッセージのコールバックをPOSTしてください。",
  "bots.setup.guide.webhook.bind.2":
    'リクエストの本文には、少なくともこのbotId・安定したuserId・`chatType: "private"`を含め、textを{command}に設定してください。',
  "bots.setup.guide.webhook.bind.3":
    "ボットがシークレットを使用している場合は、`x-zcode-bot-secret`も送信してください。連携成功後、ここに戻ってください。",
  "bots.setup.footer.choose": "対応しているボットを選んで続けてください。",
