  "settings.modelProvider.fieldHelp": "{field} について",
  "settings.modelProvider.help.contextWindow":
    "モデルが一度に処理できるコンテキストの容量で、単位はトークンです。ZCode はこの値を使ってコンテキストを管理します。\nモデルの実際の上限を超えないようにしてください。",
  "settings.modelProvider.help.maxOutputTokens":
    "モデルへの 1 回のリクエストで生成できる最大トークン数です。\nモデルの実際の上限を超えないようにしてください。",
  "settings.modelProvider.help.inputModalities":
    "モデルが受け取れるコンテンツの種類を設定します:\n\n- **テキスト**: テキストの内容を受け取ります。必須です。\n- **画像**: 画像の内容を受け取ります。\n- **動画**: 動画の内容を受け取ります。\n- **PDF**: PDF 文書をそのまま受け取ります。",
  "settings.modelProvider.help.outputModalities":
    "モデルの返答の内容の種類です。現在はテキストのみに対応しています。",
  "settings.modelProvider.help.capabilities":
    "- **構造化出力**: JSON Schema による出力フィールド・型・構造の制約に対応します。\n- **ネイティブなウェブ検索**: モデル API に組み込まれたウェブ検索機能に対応します。\n- **会話中のシステムメッセージ**: 会話の途中でシステム指示を挿入することに対応します。\n\nモデルが対応していない機能は有効にしないでください。",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "チャットで選べる推論レベルを設定します。**推論の強さが低い順から高い順に並べてください**。\nモデルが対応していない推論レベルは設定しないでください。",
  "settings.modelProvider.help.reasoningLevelMapping":
    "CEL 式を使って、現在の推論レベル `reasoningLevel` をモデル API のリクエストフィールドに対応付けます。式が返す JSON オブジェクトは、実際に送るリクエストボディにマージされます。",
  "settings.modelProvider.help.advanced":
    "**MFJS ツールスキーマ**: Moonshot Flavored JSON Schema（Moonshot の Kimi モデル API でよく使われる形式）との互換処理を有効にします。モデル API がこの形式を必要とする場合にのみ有効にしてください。",
  "settings.modelProvider.help.followRecommendedConfig":
    "モデル ID・Base URL・API 形式から、おすすめの設定を自動で当てはめます。ZCode はおすすめ設定を継続的に更新し、自動的に同期します。\n手動で設定を変更すると、その項目は手動管理になり、おすすめ設定の更新には従わなくなります。他の項目は引き続きスマート設定が管理します。",
